import React from "react";
import "../styles/Chat.css";

const ChatBox = ({ messages }) => {
    return (
        <div className="chat-box">
            {messages.map((msg, index) => (
                <div key={index} className={`message ${msg.sender}`}>

                    <div className="bubble">
                        {msg.text}
                    </div>

                </div>
            ))}
        </div>
    );
};

export default ChatBox;
